def api_call(func, tries=3, fallback=None):
    """Decorator that retries function on failure with optional fallback.

    Args:
        func: The function to decorate
        tries: Number of retry attempts (default 3)
        fallback: Optional fallback function to call after all retries fail

    Returns:
        Decorated function
    """
    @wraps(func)
    def wrapper(*args, **kwargs):
        last_exception = None
        for attempt in range(tries):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                if attempt < tries - 1:
                    continue
        # All retries failed
        if fallback:
            return fallback(*args, **kwargs)
        raise last_exception
    return wrapper

